现在开始实现 recursive_patch.py。

关键要求：
1. `DELETE` sentinel
2. 递归合并 dict，否则替换
3. 返回完全 detached 的结果（深拷贝）
4. 保持 dict 顺序：保留的 base keys 保持位置，新 keys 按 patch 出现顺序

实现：
```python
DELETE = object()

def apply_patch(base, patch, delete=DELETE):
    if not isinstance(base, dict) or not isinstance(patch, dict):
        raise TypeError("base and patch must be plain dicts")

    result = {}
    # 先处理 base 中存在的 keys
    for key in base:
        if key in patch:
            pval = patch[key]
            if pval is delete:
                continue
            bval = base[key]
            if isinstance(bval, dict) and isinstance(pval, dict):
                result[key] = apply_patch(bval, pval, delete=delete)
            else:
                # 需要深拷贝 patch 的值
                result[key] = _deep_copy(pval)
        else:
            result[key] = _deep_copy(base[key])

    # 再处理 patch 中新增的 keys（保持 patch 顺序）
    for key in patch:
        if key not in base:
            pval = patch[key]
            if pval is not delete:
                result[key] = _deep_copy(pval)

    return result

def _deep_copy(obj):
    if isinstance(obj, dict):
        return {k: _deep_copy(v) for k, v in obj.items()}
    elif isinstance(obj, list):
        return [_deep_copy(v) for v in obj]
    elif isinstance(obj, tuple):
        return tuple(_deep_copy(v) for v in obj)
    elif isinstance(obj, set):
        return {_deep_copy(v) for v in obj}
    else:
        return obj  # 不可变类型直接返回
```

